mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -2.5);
  vec3 rd = normalize(vec3(p, 1.5));
  rd.xz = rot(time * 0.15) * rd.xz;
  vec3 col = vec3(0.01, 0.01, 0.03);
  float dens = 0.0;
  for (int i = 0; i < 36; i++) {
    vec3 pos = ro + rd * float(i) * 0.12;
    float n = sin(pos.x * 2.0 + time) * cos(pos.y * 2.0) * sin(pos.z * 2.0);
    float d = smoothstep(0.3, 0.9, n);
    dens += d * 0.04;
  }
  col += vec3(0.9, 0.3, 0.1) * dens * 2.0 + vec3(0.1, 0.4, 0.9) * (dens * dens * 3.0);
  col *= (1.0 + 0.4 * bass);
  ret = col;
}
